  // Contador de visitas
  useEffect(() => {
    const hoy = new Date().toLocaleDateString("es-AR");
    setVisitCount(prev => ({ total: (prev.total||0)+1, hoy: prev.fecha===hoy ? (prev.hoy||0)+1 : 1, fecha: hoy }));
  }, []);

